const PAGE_SIZE = 40;
const LOGO_URL = "assets/images/embedded/logo-seridoplast.png";

function normalize(s){ return (s||'').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); }
function saleLabel(p){ return p.m && p.m > 1 ? `${p.u} c/${p.m}` : (p.u||'UN'); }

// ---- exportação em PDF (via impressão do navegador, sempre com a logo) ----
function buildPrintDoc(title, subtitle, columns, rows, summaryHtml){
  const thead = `<tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr>`;
  const tbody = rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('');
  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>${title}</title>
<style>
  body{ font-family:Arial, Helvetica, sans-serif; color:#1B1E22; padding:28px; }
  .print-header{ display:flex; align-items:center; gap:16px; border-bottom:3px solid #E2231A; padding-bottom:14px; margin-bottom:18px; }
  .print-header img{ height:56px; }
  .print-header h1{ font-size:19px; margin:0; color:#B81810; }
  .print-header .sub{ font-size:12.5px; color:#555; margin-top:3px; }
  table{ width:100%; border-collapse:collapse; font-size:11.5px; }
  th{ text-align:left; background:#FBE9E7; color:#B81810; padding:6px 8px; border-bottom:2px solid #E2231A; }
  td{ padding:6px 8px; border-bottom:1px solid #eee; }
  tr:nth-child(even) td{ background:#FAFAFA; }
  .print-summary{ margin-top:14px; font-size:12.5px; font-weight:bold; color:#1B1E22; text-align:right; }
  .print-footer{ margin-top:24px; font-size:10.5px; color:#888; text-align:center; }
  @media print{ body{ padding:8px; } }
</style></head>
<body>
  <div class="print-header">
    <img src="${LOGO_URL}" alt="Seridóplast">
    <div><h1>${title}</h1><div class="sub">${subtitle}</div></div>
  </div>
  <table><thead>${thead}</thead><tbody>${tbody}</tbody></table>
  ${summaryHtml ? `<div class="print-summary">${summaryHtml}</div>` : ''}
  <div class="print-footer">Gerado em ${new Date().toLocaleString('pt-BR')} · Catálogo Seridóplast</div>
</body></html>`;
}

// Catálogo do fornecedor: documento comercial limpo, grade 4 colunas com linhas finas, cabeçalho e rodapé com paginação
function titleCase(s){
  return (s||'').toString().toLowerCase().replace(/(^|\s)\S/g, c => c.toUpperCase());
}

function loadImageDims(dataUrl){
  return new Promise(resolve=>{
    const img = new Image();
    img.onload = ()=> resolve({w: img.naturalWidth, h: img.naturalHeight});
    img.onerror = ()=> resolve(null);
    img.src = dataUrl;
  });
}

function loadImageElement(src){
  return new Promise(resolve=>{
    const img = new Image();
    img.onload = ()=> resolve(img);
    img.onerror = ()=> resolve(null);
    try{ img.src = src.startsWith('data:') ? src : new URL(src, document.baseURI).href; }
    catch(e){ resolve(null); }
  });
}

function loadPdfImage(src){
  return new Promise(resolve=>{
    if(!src){ resolve(null); return; }
    let settled = false;
    const finish = value=>{
      if(settled) return;
      settled = true;
      clearTimeout(timeout);
      resolve(value);
    };
    const timeout = setTimeout(()=>finish(null), 20000);
    const img = new Image();
    img.onload = ()=>{
      try{
        if(!img.naturalWidth || !img.naturalHeight){ finish(null); return; }
        const maxEdge = 900;
        const resizeScale = Math.min(1, maxEdge / Math.max(img.naturalWidth, img.naturalHeight));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(img.naturalWidth * resizeScale));
        canvas.height = Math.max(1, Math.round(img.naturalHeight * resizeScale));
        const context = canvas.getContext('2d');
        context.fillStyle = '#FFFFFF';
        context.fillRect(0, 0, canvas.width, canvas.height);
        context.drawImage(img, 0, 0, canvas.width, canvas.height);
        finish({ w:canvas.width, h:canvas.height, data:canvas.toDataURL('image/jpeg', .86) });
      }catch(e){ finish(null); }
    };
    img.onerror = ()=>finish(null);
    img.decoding = 'async';
    try{
      img.src = src.startsWith('data:') ? src : new URL(src, document.baseURI).href;
    }catch(e){
      finish(null);
    }
  });
}

// Gera o PDF do catálogo do fornecedor desenhando diretamente (sem "tirar print" da tela) e baixa automaticamente.
async function generateSupplierPDF(filename, title, itemsIn){
  if(typeof window.jspdf === 'undefined'){
    alert('Não foi possível carregar o gerador de PDF (é necessário estar conectado à internet na primeira vez). Tente novamente com internet disponível.');
    return;
  }
  const items = itemsIn; // mesma ordem do catálogo virtual (ordem da planilha)
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'mm', format:'a4', orientation:'portrait' });

  const pageW = 210, pageH = 297, margin = 12;
  const cols = 3, rows = 5, perPage = cols*rows;
  const cellW = (pageW - margin*2) / cols;
  const gridTop = 49;
  const gridBottom = pageH - 14; // espaço reservado pro rodapé
  const cellH = (gridBottom - gridTop) / rows;

  const segs = [...new Set(items.map(p=>p.k))];
  const segLabel = segs.length === 1
    ? titleCase(segs[0])
    : segs.length <= 3
      ? segs.map(titleCase).join(', ')
      : `${segs.slice(0,2).map(titleCase).join(', ')} e mais ${segs.length-2}`;

  // Carrega somente as fotos da página atual para evitar falhas de memória em fornecedores grandes.
  async function loadPageImages(pageItems){
    const pageImages = {};
    await Promise.all(pageItems.map(async p=>{
      const src = PRODUCT_IMAGES[p.c];
      if(!src) return;
      const image = await loadPdfImage(src);
      if(image) pageImages[p.c] = image;
    }));
    return pageImages;
  }
  const logoImage = await loadImageElement(LOGO_URL);
  const logoDims = logoImage ? {w:logoImage.naturalWidth, h:logoImage.naturalHeight} : null;
  const productsWithImage = items.filter(p=>PRODUCT_IMAGES[p.c]).length;

  const totalPages = Math.max(1, Math.ceil(items.length / perPage));

  function drawFooter(pageNum){
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(140,140,140);
    doc.setFillColor(226,35,26); doc.rect(margin, pageH-11, 1.6, 1.6, 'F');
    doc.text(`Seridóplast · ${titleCase(title)} · Catálogo Comercial`, margin+3.5, pageH-9.7);
    doc.text(`Página ${pageNum} de ${totalPages}`, pageW-margin, pageH-9.7, {align:'right'});
  }

  function drawHeader(){
    doc.setFillColor(255,248,247); doc.rect(0, 0, pageW, pageH, 'F');
    doc.setFillColor(255,255,255); doc.roundedRect(margin, 11, pageW-margin*2, 31, 2.5, 2.5, 'F');
    doc.setDrawColor(241,194,188); doc.roundedRect(margin, 11, pageW-margin*2, 31, 2.5, 2.5, 'S');
    doc.setDrawColor(226,35,26); doc.setFillColor(226,35,26);
    doc.rect(0, 0, pageW, 2.3, 'F');
    if(logoDims){
      const lh = 13.5, lw = lh * (logoDims.w/logoDims.h);
      doc.addImage(logoImage, 'PNG', margin+4, 15, lw, lh);
    }
    doc.setFont('helvetica','bold'); doc.setFontSize(14); doc.setTextColor(184,24,16);
    doc.text(titleCase(title), margin+34, 19.5);
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(35,35,35);
    doc.text(`Catálogo de produtos · ${segLabel}`, margin+34, 25.5);
    doc.setFont('helvetica','italic'); doc.setFontSize(8.5); doc.setTextColor(120,50,45);
    doc.text('Acreditamos na força do trabalho', margin+34, 31.5);
    doc.setFont('helvetica','normal'); doc.setFontSize(7.8); doc.setTextColor(125,125,125);
    doc.text(`${items.length} produto(s) · ${productsWithImage} com foto · sequência fiel ao catálogo digital`, margin+34, 37);
  }

  function drawCell(p, x, y, w, h, pageImages){
    doc.setFillColor(249,225,222); doc.roundedRect(x+1.2, y+1.2, w-2.4, h-2.4, 2, 2, 'F');
    doc.setFillColor(255,255,255); doc.roundedRect(x+.4, y+.4, w-2.4, h-2.4, 2, 2, 'F');
    doc.setDrawColor(241,205,201); doc.roundedRect(x+.4, y+.4, w-2.4, h-2.4, 2, 2, 'S');
    const imgBoxW = w - 8, imgBoxH = h * 0.52;
    const imgBoxX = x + 4, imgBoxY = y + 3;
    const d = pageImages[p.c];
    if(d){
      const scale = Math.min(imgBoxW/d.w, imgBoxH/d.h);
      const dw = d.w*scale, dh = d.h*scale;
      const dx = imgBoxX + (imgBoxW-dw)/2, dy = imgBoxY + (imgBoxH-dh)/2;
      try{ doc.addImage(d.data, 'JPEG', dx, dy, dw, dh); }catch(e){}
    }else{
      doc.setFillColor(245,245,245); doc.rect(imgBoxX, imgBoxY, imgBoxW, imgBoxH, 'F');
      doc.setFont('helvetica','normal'); doc.setFontSize(7); doc.setTextColor(170,170,170);
      doc.text('Sem foto', x+w/2, imgBoxY+imgBoxH/2, {align:'center'});
    }
    const textY = imgBoxY + imgBoxH + 4.5;
    doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(27,30,34);
    const nameLines = doc.splitTextToSize(titleCase(p.d), w-8).slice(0,3);
    doc.text(nameLines, x+w/2, textY, {align:'center'});
    doc.setFont('helvetica','bold'); doc.setFontSize(7.2); doc.setTextColor(184,24,16);
    doc.text(`COD ${p.c}`, x+w/2, y+h-4.5, {align:'center'});
  }

  let pageNum = 0;
  const itemCountForLoop = Math.max(items.length, 1);
  for(let pageStart=0; pageStart<itemCountForLoop; pageStart+=perPage){
    if(pageNum > 0){
      doc.addPage();
    }
    pageNum++;
    drawHeader();
    const pageItems = items.slice(pageStart, pageStart+perPage);
    const pageImages = await loadPageImages(pageItems);
    for(let position=0; position<pageItems.length; position++){
      const col = position % cols, row = Math.floor(position / cols);
      const x = margin + col*cellW, y = gridTop + row*cellH;
      drawCell(pageItems[position], x, y, cellW, cellH, pageImages);
    }
    drawFooter(pageNum);
  }

  doc.save(filename);
}

function buildSupplierCatalogDoc(title, subtitle, itemsIn){
  const items = itemsIn; // mesma ordem do catálogo virtual (ordem da planilha)
  const PER_PAGE = 15; // 3 x 5
  const pages = [];
  for(let i=0; i<items.length; i+=PER_PAGE){ pages.push(items.slice(i, i+PER_PAGE)); }
  if(pages.length === 0) pages.push([]);
  const totalPages = pages.length;

  const segs = [...new Set(items.map(p=>p.k))];
  const segLabel = segs.length === 1
    ? titleCase(segs[0])
    : segs.length <= 3
      ? segs.map(titleCase).join(', ')
      : `${segs.slice(0,2).map(titleCase).join(', ')} e mais ${segs.length-2}`;

  const cellHTML = (p)=>{
    const photo = PRODUCT_IMAGES[p.c];
    const photoHTML = photo
      ? `<img class="pc-photo" src="${photo}" alt="${p.d}">`
      : `<div class="pc-noimg">Sem foto</div>`;
    return `<div class="pcell">
      <div class="pc-imgwrap">${photoHTML}</div>
      <div class="pc-name">${titleCase(p.d)}</div>
      <div class="pc-code">COD ${p.c}</div>
    </div>`;
  };

  const pagesHTML = pages.map((pageItems, idx)=>{
    const header = idx === 0 ? `
      <div class="print-topline"></div>
      <div class="print-header">
        <img src="${LOGO_URL}" alt="Seridóplast">
        <div class="ph-text"><h1>${titleCase(title)}</h1><div class="sub">Catálogo de produtos · ${segLabel}</div></div>
      </div>
      <div class="print-count">${items.length} produto(s) · catálogo organizado para apresentação comercial</div>
    ` : `<div class="print-topline"></div>`;
    return `<div class="print-page">
      <div class="page-body">
        ${header}
        <div class="grid-wrap"><div class="grid-page">${pageItems.map(cellHTML).join('')}</div></div>
      </div>
      <div class="print-footer"><span class="pf-dot"></span>Seridóplast · Catálogo Comercial<span class="pf-page">Página ${idx+1}${totalPages>1 ? ' de '+totalPages : ''}</span></div>
    </div>`;
  }).join('');

  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>${title}</title>
<style>
  *{box-sizing:border-box;}
  body{ font-family:Arial, Helvetica, sans-serif; color:#1B1E22; margin:0; padding:0; background:#fff; }
  .print-page{ padding:22px 26px 14px; display:flex; flex-direction:column; min-height:100vh; page-break-after:always; }
  .print-page:last-child{ page-break-after:auto; }
  .page-body{ flex:1; }
  .print-topline{ height:4px; background:#E2231A; margin-bottom:18px; }
  .print-header{ display:flex; align-items:center; gap:18px; margin-bottom:10px; }
  .print-header img{ height:52px; }
  .ph-text h1{ font-size:20px; margin:0; color:#B81810; font-weight:700; }
  .ph-text .sub{ font-size:14px; color:#1B1E22; font-weight:600; margin-top:2px; }
  .print-count{ font-size:10.5px; color:#777; margin-bottom:14px; }
  .grid-wrap{ border:1px solid #ddd; }
  .grid-page{ display:grid; grid-template-columns:repeat(3, 1fr); }
  .pcell{
    border-right:1px solid #ddd; border-bottom:1px solid #ddd;
    padding:16px 12px; display:flex; flex-direction:column; align-items:center; text-align:center;
    min-height:190px;
  }
  .pcell:nth-child(3n){ border-right:none; }
  .pc-imgwrap{ flex:1; display:flex; align-items:center; justify-content:center; width:100%; margin-bottom:10px; }
  .pc-photo{ max-width:92%; max-height:150px; object-fit:contain; }
  .pc-noimg{
    width:70%; height:100px; display:flex; align-items:center; justify-content:center;
    background:#F5F5F5; color:#aaa; font-size:9px; border-radius:4px;
  }
  .pc-name{ font-size:12px; font-weight:700; line-height:1.3; color:#1B1E22; margin-bottom:4px; }
  .pc-code{ font-size:10px; font-weight:700; color:#1B1E22; }
  .print-footer{
    display:flex; align-items:center; justify-content:space-between;
    font-size:9px; color:#888; padding-top:10px; margin-top:14px;
  }
  .pf-dot{ display:inline-block; width:7px; height:7px; background:#E2231A; margin-right:6px; vertical-align:middle; }
  @page{ size:A4 portrait; margin:8mm; }
</style></head>
<body>
  ${pagesHTML}
</body></html>`;
}

function exportPDF(filename, html){
  let url;
  try{
    const blob = new Blob([html], {type:'text/html'});
    url = URL.createObjectURL(blob);
  }catch(err){
    alert('Não foi possível gerar o arquivo de exportação neste navegador.');
    return;
  }
  const w = window.open(url, '_blank');
  if(!w){
    alert('Não foi possível abrir a janela de exportação. Verifique se pop-ups estão bloqueados no navegador para este site/arquivo.');
    URL.revokeObjectURL(url);
    return;
  }
  alert('Vai abrir a tela de impressão. Para baixar o PDF: em "Destino" (ou "Impressora"), escolha "Salvar como PDF" e depois clique em "Salvar".');
  const triggerPrint = ()=>{ try{ w.focus(); w.print(); }catch(e){} };
  w.addEventListener('load', triggerPrint);
  setTimeout(triggerPrint, 700);
  setTimeout(()=> URL.revokeObjectURL(url), 60000);
}

const TILE_GRADIENTS = [
  'linear-gradient(135deg,#E2231A,#F1573D)',
  'linear-gradient(135deg,#B81810,#E2231A)',
  'linear-gradient(135deg,#8C1712,#C43A2E)',
  'linear-gradient(135deg,#D62828,#FF6B4A)',
  'linear-gradient(135deg,#A81F1F,#D6483A)',
  'linear-gradient(135deg,#7A1410,#B5372A)'
];
function hashStr(s){ let h=0; for(let i=0;i<s.length;i++){ h=(h*31+s.charCodeAt(i))>>>0; } return h; }
function gradientFor(key){ return TILE_GRADIENTS[ hashStr(key) % TILE_GRADIENTS.length ]; }
function avatarGradient(key){
  return 'radial-gradient(circle at 32% 26%, rgba(255,255,255,0.65), rgba(255,255,255,0) 46%), ' + gradientFor(key);
}

const ICONS = {
  box: '<rect x="8" y="18" width="32" height="22" rx="2"/><polyline points="8,18 24,10 40,18"/><line x1="24" y1="10" x2="24" y2="40"/>',
  gift: '<rect x="8" y="20" width="32" height="20" rx="2"/><line x1="24" y1="20" x2="24" y2="40"/><line x1="8" y1="28" x2="40" y2="28"/><path d="M24 20c-4-9-15-8-15 0"/><path d="M24 20c4-9 15-8 15 0"/>',
  balloon: '<circle cx="24" cy="18" r="12"/><path d="M20 30 L24 34 L28 30 Z"/><path d="M24 34 q5 6 -2 10"/>',
  cupcake: '<path d="M14 24 L34 24 L31 40 L17 40 Z"/><path d="M14 24 q10-15 20 0"/><line x1="24" y1="8" x2="24" y2="15"/>',
  candy: '<path d="M18 24 L8 17 L8 31 Z"/><path d="M30 24 L40 17 L40 31 Z"/><rect x="18" y="18" width="12" height="12" rx="4"/>',
  spray: '<rect x="16" y="18" width="16" height="22" rx="2"/><rect x="20" y="9" width="8" height="9" rx="1"/><line x1="24" y1="4" x2="24" y2="9"/><line x1="31" y1="7" x2="35" y2="4"/>',
  bag: '<path d="M14 18 L34 18 L32 41 L16 41 Z"/><path d="M18 18 q0-9 6-9 q6 0 6 9"/>',
  tray: '<rect x="8" y="15" width="32" height="21" rx="2"/><line x1="8" y1="26" x2="40" y2="26"/><line x1="20" y1="15" x2="20" y2="36"/><line x1="30" y1="15" x2="30" y2="36"/>',
  paper: '<rect x="14" y="6" width="20" height="34" rx="2"/><line x1="18" y1="15" x2="30" y2="15"/><line x1="18" y1="22" x2="30" y2="22"/><line x1="18" y1="29" x2="26" y2="29"/>'
};
function iconFor(cat){
  const c = normalize(cat);
  if(c.includes('bombonier') || c.includes('doce')) return ICONS.candy;
  if(c.includes('confeitaria')) return ICONS.cupcake;
  if(c.includes('festa e decora') || c.includes('cesta')) return ICONS.balloon;
  if(c.includes('festa e acessorio') || c.includes('acessorio') || c === 'festa') return ICONS.gift;
  if(c.includes('sacos e sacolas')) return ICONS.bag;
  if(c.includes('papei') || c.includes('papelaria') || c.includes('pepelaria')) return ICONS.paper;
  if(c.includes('limpeza')) return ICONS.spray;
  if(c.includes('foodservice')) return ICONS.tray;
  if(c.includes('embalage') || c.includes('formas e c')) return ICONS.box;
  return ICONS.box;
}

