const catCounts = {};
for(const p of PRODUCTS){ catCounts[p.k] = (catCounts[p.k]||0) + 1; }
const SEG_PRIORITY = ['CONFEITARIA', 'EMBALAGEM', 'BOMBONIERI'];
const catsSorted = Object.keys(catCounts).sort((a,b)=>{
  const ai = SEG_PRIORITY.indexOf(a);
  const bi = SEG_PRIORITY.indexOf(b);
  if(ai !== -1 || bi !== -1){
    if(ai === -1) return 1;
    if(bi === -1) return -1;
    return ai - bi;
  }
  return catCounts[b] - catCounts[a];
});
