const groupedView = document.getElementById('groupedView');
groupedView.addEventListener('click', (e)=>{
  const card = e.target.closest('[data-supplier-drill]'); if(!card) return;
  state.supplier = card.dataset.supplierDrill;
  state.page = 1;
  render();
});

function render(){
  updateSidebarActive();
  const active = !!state.query || !!state.category || !!state.supplier;
  if(!active){
    landingSection.style.display = 'block';
    resultsSection.style.display = 'none';
    return;
  }
  landingSection.style.display = 'none';
  resultsSection.style.display = 'block';

  const q = normalize(state.query);
  const filtered = PRODUCTS.filter(p=>{
    if(state.category && p.k !== state.category) return false;
    if(state.supplier && p.f !== state.supplier) return false;
    if(q && !(normalize(p.d).includes(q) || normalize(p.c).includes(q) || normalize(p.f).includes(q))) return false;
    return true;
  });

  const pills = [];
  pills.push(`<button class="backbtn" id="backBtn">← Voltar</button>`);
  if(state.supplier) pills.push(`<div class="filter-pill">Fornecedor: ${state.supplier}<button data-clear="supplier">×</button></div>`);
  if(state.category) pills.push(`<div class="filter-pill">Segmento: ${state.category}<button data-clear="category">×</button></div>`);
  if(state.query) pills.push(`<div class="filter-pill">"${state.query}"<button data-clear="query">×</button></div>`);
  pills.push(`<span style="font-size:12.5px;color:var(--ink-soft);">${filtered.length} resultado(s)</span>`);
  if(state.supplier) pills.push(`<button class="export-btn" id="exportSupplierBtn">⬇ Exportar catálogo (PDF)</button>`);
  pills.push(`<button class="clearall" id="clearAllBtn">Limpar tudo</button>`);
  filterBar.innerHTML = pills.join('');

  if(filtered.length === 0){
    grid.style.display = 'none'; groupedView.style.display = 'none';
    emptyEl.style.display = 'block'; pagerEl.style.display = 'none';
    return;
  }
  emptyEl.style.display = 'none';

  // Segmento selecionado sem fornecedor/busca específica -> mostrar fornecedores em grid (igual à tela inicial)
  const shouldGroup = !!state.category && !state.supplier && !state.query;

  if(shouldGroup){
    grid.style.display = 'none'; pagerEl.style.display = 'none';
    groupedView.style.display = 'block';

    const groups = {};
    for(const p of filtered){
      const key = p.f || 'SEM FORNECEDOR';
      (groups[key] = groups[key] || []).push(p);
    }
    const groupNames = Object.keys(groups).sort((a,b)=> groups[b].length - groups[a].length);

    groupedView.innerHTML = `<div class="supplier-grid">${groupNames.map(g=>{
      const initials = g.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
      return `<div class="supplier-card" data-supplier-drill="${g}">
        <div class="supplier-avatar" style="background:${avatarGradient(g)}">${initials}</div>
        <div class="s-name">${g}</div>
        <div class="s-count">${groups[g].length} itens</div>
      </div>`;
    }).join('')}</div>`;
    return;
  }

  groupedView.style.display = 'none';
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  if(state.page > totalPages) state.page = totalPages;
  const start = (state.page-1) * PAGE_SIZE;
  const pageItems = filtered.slice(start, start + PAGE_SIZE);

  grid.style.display = 'grid';
  grid.innerHTML = pageItems.map(cardHTML).join('');

  pagerEl.style.display = totalPages > 1 ? 'flex' : 'none';
  pageInfo.textContent = `Página ${state.page} de ${totalPages}`;
  prevBtn.disabled = state.page <= 1;
  nextBtn.disabled = state.page >= totalPages;
}

filterBar.addEventListener('click', (e)=>{
  if(e.target.id === 'backBtn'){
    if(state.query){
      state.query = '';
      searchInput.value = '';
    } else if(state.supplier){
      state.supplier = '';
    } else if(state.category){
      state.category = '';
    }
    state.page = 1;
    render();
    return;
  }
  const clearBtn = e.target.closest('[data-clear]');
  if(clearBtn){
    const key = clearBtn.dataset.clear;
    state[key] = '';
    if(key === 'query') searchInput.value = '';
    state.page = 1;
    render();
    return;
  }
  if(e.target.id === 'clearAllBtn'){
    state.query=''; state.category=''; state.supplier=''; state.page=1;
    searchInput.value = '';
    render();
    return;
  }
  if(e.target.id === 'exportSupplierBtn'){
    const btn = e.target;
    const items = bySupplier[state.supplier] || [];
    const safeName = state.supplier.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
    const origText = btn.textContent;
    btn.textContent = 'Gerando PDF…';
    btn.disabled = true;
    generateSupplierPDF(`catalogo-${safeName}.pdf`, state.supplier, items).finally(()=>{
      btn.textContent = origText;
      btn.disabled = false;
    });
  }
});

