const priceProductMeta = document.getElementById('priceProductMeta');
const priceValidation = document.getElementById('priceValidation');
const cancelPriceBtn = document.getElementById('cancelPriceBtn');
const confirmPriceBtn = document.getElementById('confirmPriceBtn');
const rcaSelect = document.getElementById('rcaSelect');
const manageRcasBtn = document.getElementById('manageRcasBtn');
const rcaOverlay = document.getElementById('rcaOverlay');
const closeRcaBtn = document.getElementById('closeRcaBtn');
const rcaForm = document.getElementById('rcaForm');
const rcaName = document.getElementById('rcaName');
const rcaEmail = document.getElementById('rcaEmail');
const rcaPhone = document.getElementById('rcaPhone');
const rcaList = document.getElementById('rcaList');
const requestValidation = document.getElementById('requestValidation');
const requestOverlay = document.getElementById('requestOverlay');
const requestPreview = document.getElementById('requestPreview');
const closeRequestBtn = document.getElementById('closeRequestBtn');
const RCA_STORAGE_KEY = 'seridoplast-rcas-v1';
let rcas = [];

try{ rcas = JSON.parse(localStorage.getItem(RCA_STORAGE_KEY) || '[]'); }
catch(e){ rcas = []; }
if(!Array.isArray(rcas)) rcas = [];

function escapeHtml(value){
  return String(value || '').replace(/[&<>'"]/g, ch=>({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[ch]));
}

const currencyFormatter = new Intl.NumberFormat('pt-BR', { style:'currency', currency:'BRL' });
function formatCurrency(value){ return currencyFormatter.format(Number(value) || 0); }
function parseOptionalPrice(value){
  let normalized = String(value || '').trim();
  if(!normalized) return null;
  normalized = normalized.replace(/[^\d,.-]/g, '');
  const lastComma = normalized.lastIndexOf(',');
  const lastDot = normalized.lastIndexOf('.');
  const decimalIndex = Math.max(lastComma, lastDot);
  if(decimalIndex >= 0){
    const integerPart = normalized.slice(0, decimalIndex).replace(/[^\d-]/g, '');
    const decimalPart = normalized.slice(decimalIndex+1).replace(/\D/g, '');
    normalized = `${integerPart}.${decimalPart}`;
  }else{
    normalized = normalized.replace(/[^\d-]/g, '');
  }
  const parsed = Number(normalized);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : NaN;
}

let pendingPriceItem = null;
function openPriceDialog(code, qty, editOnly=false){
  const product = PRODUCTS_BY_CODE[code];
  if(!product) return;
  pendingPriceItem = { code, qty, editOnly };
  priceProductName.textContent = product.d;
  priceProductMeta.textContent = editOnly
    ? `Código ${product.c} · alterando o preço do item`
    : `Código ${product.c} · quantidade: ${qty} ${product.u}`;
  priceInput.value = Object.prototype.hasOwnProperty.call(cartPrices, code)
    ? Number(cartPrices[code]).toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 })
    : '';
  priceValidation.textContent = '';
  priceValidation.classList.remove('show');
  confirmPriceBtn.textContent = editOnly ? 'Salvar preço' : 'Adicionar ao pedido';
  priceOverlay.classList.add('open');
  setTimeout(()=>priceInput.focus(), 50);
}

function closePriceDialog(){
  priceOverlay.classList.remove('open');
  pendingPriceItem = null;
  priceForm.reset();
  priceValidation.classList.remove('show');
}

cancelPriceBtn.addEventListener('click', closePriceDialog);
priceOverlay.addEventListener('click', e=>{ if(e.target === priceOverlay) closePriceDialog(); });
priceForm.addEventListener('submit', e=>{
  e.preventDefault();
  if(!pendingPriceItem) return;
  const rawPrice = priceInput.value.trim();
  const price = parseOptionalPrice(rawPrice);
  if(Number.isNaN(price)){
    priceValidation.textContent = 'Informe um preço válido ou deixe o campo em branco.';
    priceValidation.classList.add('show');
    return;
  }
  const { code, qty, editOnly } = pendingPriceItem;
  if(price === null) delete cartPrices[code];
  else cartPrices[code] = price;
  if(!editOnly) cart[code] = (cart[code] || 0) + qty;
  closePriceDialog();
  updateCartUI();
  syncCardCartState(code);
});

function saveRcas(){
  localStorage.setItem(RCA_STORAGE_KEY, JSON.stringify(rcas));
  renderRcaOptions();
  renderRcaList();
}

function renderRcaOptions(){
  const current = rcaSelect.value;
  rcaSelect.innerHTML = `<option value="">${rcas.length ? 'Selecione um RCA' : 'Cadastre o primeiro RCA'}</option>` +
    rcas.map(rca=>`<option value="${escapeHtml(rca.id)}">${escapeHtml(rca.name)}</option>`).join('');
  if(rcas.some(rca=>rca.id === current)) rcaSelect.value = current;
}

function renderRcaList(){
  rcaList.innerHTML = rcas.length ? rcas.map(rca=>`<div class="rca-row">
    <div class="rca-main"><strong>${escapeHtml(rca.name)}</strong><small>${escapeHtml([rca.email, rca.phone].filter(Boolean).join(' · ') || 'Sem contato informado')}</small></div>
    <button type="button" data-remove-rca="${escapeHtml(rca.id)}">Remover</button>
  </div>`).join('') : '<div class="cart-empty">Nenhum RCA cadastrado.</div>';
}

function selectedRca(){ return rcas.find(rca=>rca.id === rcaSelect.value) || null; }

manageRcasBtn.addEventListener('click', ()=>{
  renderRcaList(); rcaOverlay.classList.add('open'); setTimeout(()=>rcaName.focus(), 50);
});
closeRcaBtn.addEventListener('click', ()=>rcaOverlay.classList.remove('open'));
rcaOverlay.addEventListener('click', e=>{ if(e.target === rcaOverlay) rcaOverlay.classList.remove('open'); });
rcaForm.addEventListener('submit', e=>{
  e.preventDefault();
  const entry = {
    id: (crypto.randomUUID ? crypto.randomUUID() : `rca-${Date.now()}`),
    name: rcaName.value.trim(), email:rcaEmail.value.trim(), phone:rcaPhone.value.trim()
  };
  if(!entry.name) return;
  rcas.push(entry); saveRcas(); rcaSelect.value = entry.id; rcaForm.reset();
});
rcaList.addEventListener('click', e=>{
  const button = e.target.closest('[data-remove-rca]'); if(!button) return;
  rcas = rcas.filter(rca=>rca.id !== button.dataset.removeRca); saveRcas();
});
renderRcaOptions();

document.body.addEventListener('click', function(e){
  const step = e.target.closest('[data-step]');
  if(step){
    const input = document.querySelector(`input[data-qtyfor="${CSS.escape(step.dataset.code)}"]`);
    let v = parseInt(input.value,10) || 1;
    v += parseInt(step.dataset.step,10);
    if(v < 1) v = 1;
    input.value = v;
    return;
  }
  const btn = e.target.closest('[data-addfor]');
  if(!btn) return;
  const code = btn.dataset.addfor;
  const input = document.querySelector(`input[data-qtyfor="${CSS.escape(code)}"]`);
  let qty = parseInt(input.value, 10);
  if(!qty || qty < 1) qty = 1;
  openPriceDialog(code, qty);
});

function syncCardCartState(code){
  const inCart = !!cart[code];
  document.querySelectorAll(`.card[data-code="${CSS.escape(code)}"]`).forEach(card=>{
    card.classList.toggle('in-cart', inCart);
    let badge = card.querySelector('.in-cart-badge');
    if(inCart && !badge){
      const tile = card.querySelector('.tile');
      if(tile){ tile.insertAdjacentHTML('beforeend', '<span class="in-cart-badge">✓ No pedido</span>'); }
    } else if(!inCart && badge){
      badge.remove();
    }
    const addBtn = card.querySelector('[data-addfor]');
    if(addBtn){
      addBtn.classList.toggle('added', inCart);
      const svg = addBtn.querySelector('svg');
      addBtn.innerHTML = '';
      if(svg) addBtn.appendChild(svg);
      addBtn.append(inCart ? ' Adicionado ✓' : ' Adicionar');
    }
  });
}

function updateCartUI(){
  const codes = Object.keys(cart);
  const totalItems = codes.reduce((a,c)=>a+cart[c],0);
  cartBadge.textContent = totalItems;
  mobileBar.classList.toggle('show', totalItems > 0);
  mobileBarTxt.textContent = `${totalItems} ${totalItems===1?'item':'itens'} no pedido`;

  if(codes.length === 0){
    cartList.innerHTML = `<div class="cart-empty">Nenhum item adicionado ainda.<br>Escolha a quantidade em cada produto e toque em "Adicionar".</div>`;
    cartTotal.textContent = '';
    return;
  }
  const totalItens = codes.reduce((a,c)=>a+cart[c],0);
  const pricedCodes = codes.filter(code=>Object.prototype.hasOwnProperty.call(cartPrices, code));
  const totalPrice = pricedCodes.reduce((sum, code)=>sum + cart[code] * cartPrices[code], 0);
  cartList.innerHTML = codes.map(code=>{
    const p = PRODUCTS_BY_CODE[code];
    const qty = cart[code];
    const hasPrice = Object.prototype.hasOwnProperty.call(cartPrices, code);
    const priceLine = hasPrice
      ? `${formatCurrency(cartPrices[code])} un. · ${formatCurrency(cartPrices[code] * qty)}`
      : 'Preço não informado';
    return `<div class="cart-item">
      <div class="ci-name">${p.d}<br><span class="ci-code">${p.c} · ${p.f}</span></div>
      <div class="ci-values"><div class="ci-qty">${qty} ${p.u}</div><div class="ci-price">${priceLine}</div><button type="button" class="ci-edit-price" data-edit-price="${code}">Editar preço</button></div>
      <button class="ci-remove" data-removecode="${code}">×</button>
    </div>`;
  }).join('');
  const priceSummary = pricedCodes.length
    ? ` · Valor informado: ${formatCurrency(totalPrice)}${pricedCodes.length < codes.length ? ` · ${codes.length-pricedCodes.length} sem preço` : ''}`
    : ' · Preços não informados';
  cartTotal.textContent = `Total: ${codes.length} produto(s) · ${totalItens} ${totalItens===1?'volume':'volumes'}${priceSummary}`;
}

cartList.addEventListener('click', function(e){
  const editPriceBtn = e.target.closest('[data-edit-price]');
  if(editPriceBtn){
    openPriceDialog(editPriceBtn.dataset.editPrice, 0, true);
    return;
  }
  const btn = e.target.closest('[data-removecode]');
  if(!btn) return;
  const code = btn.dataset.removecode;
  delete cart[code];
  delete cartPrices[code];
  updateCartUI();
  syncCardCartState(code);
});

function openCart(){ requestValidation.classList.remove('show'); cartOverlay.classList.add('open'); }
cartBtn.addEventListener('click', openCart);
mobileBarBtn.addEventListener('click', openCart);
closeCartBtn.addEventListener('click', ()=> cartOverlay.classList.remove('open'));
cartOverlay.addEventListener('click', (e)=>{ if(e.target === cartOverlay) cartOverlay.classList.remove('open'); });
clearBtn.addEventListener('click', ()=>{
  const codes = Object.keys(cart);
  cart = {};
  cartPrices = {};
  updateCartUI();
  codes.forEach(syncCardCartState);
});

function buildOrderText(){
  const codes = Object.keys(cart);
  if(codes.length === 0) return '';
  const rca = selectedRca();
  let lines = ['SOLICITAÇÃO DE PRODUTOS — SERIDÓPLAST', 'Acreditamos na força do trabalho', ''];
  if(rca){
    lines.push(`RCA: ${rca.name}`);
    if(rca.email) lines.push(`E-mail: ${rca.email}`);
    if(rca.phone) lines.push(`WhatsApp: ${rca.phone}`);
    lines.push('');
  }
  for(const code of codes){
    const p = PRODUCTS_BY_CODE[code];
    const qty = cart[code];
    const hasPrice = Object.prototype.hasOwnProperty.call(cartPrices, code);
    const priceText = hasPrice
      ? ` - Preço un.: ${formatCurrency(cartPrices[code])} - Total: ${formatCurrency(cartPrices[code] * qty)}`
      : ' - Preço: não informado';
    lines.push(`${p.c} - ${p.d} - ${qty} ${p.u}${priceText}`);
  }
  const totalItens = codes.reduce((a,c)=>a+cart[c],0);
  const pricedCodes = codes.filter(code=>Object.prototype.hasOwnProperty.call(cartPrices, code));
  const totalPrice = pricedCodes.reduce((sum, code)=>sum + cart[code] * cartPrices[code], 0);
  lines.push('');
  lines.push(`Total: ${codes.length} produto(s), ${totalItens} ${totalItens===1?'volume':'volumes'}`);
  if(pricedCodes.length) lines.push(`Valor informado: ${formatCurrency(totalPrice)}${pricedCodes.length < codes.length ? ` (${codes.length-pricedCodes.length} item(ns) sem preço)` : ''}`);
  else lines.push('Preços não informados.');
  return lines.join('\n');
}

function validateRequest(){
  let message = '';
  if(Object.keys(cart).length === 0) message = 'Adicione pelo menos um produto.';
  else if(!selectedRca()) message = 'Selecione ou cadastre um RCA antes de preparar a solicitação.';
  requestValidation.textContent = message;
  requestValidation.classList.toggle('show', !!message);
  return !message;
}

prepareBtn.addEventListener('click', ()=>{
  if(!validateRequest()) return;
  requestPreview.textContent = buildOrderText();
  cartOverlay.classList.remove('open');
  requestOverlay.classList.add('open');
});

closeRequestBtn.addEventListener('click', ()=>requestOverlay.classList.remove('open'));
requestOverlay.addEventListener('click', e=>{ if(e.target === requestOverlay) requestOverlay.classList.remove('open'); });

copyBtn.addEventListener('click', async ()=>{
  const text = buildOrderText();
  if(!text) return;
  try{
    await navigator.clipboard.writeText(text);
    copyBtn.textContent = 'Copiado ✓';
  }catch(err){
    const ta = document.createElement('textarea');
    ta.value = text; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
    copyBtn.textContent = 'Copiado ✓';
  }
  setTimeout(()=>{ copyBtn.textContent = 'Copiar rascunho'; }, 1300);
});

// Pedido: gera o PDF com foto, quantidade e preço opcional, e baixa automaticamente.
async function generateOrderPDF(filename, items, summaryText, rca){
  if(typeof window.jspdf === 'undefined'){
    alert('Não foi possível carregar o gerador de PDF (é necessário estar conectado à internet na primeira vez). Tente novamente com internet disponível.');
    return;
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'mm', format:'a4', orientation:'portrait' });
  const pageW = 210, pageH = 297, margin = 14;
  const columns = ['Foto','Código','Produto','Qtd.','Preço un.','Total'];
  const colWidths = [22, 20, 64, 22, 27, 27];
  const rowH = 18;
  const rowsPerPage = 12;
  const totalPages = Math.max(1, Math.ceil(items.length / rowsPerPage));
  const logoImage = await loadImageElement(LOGO_URL);
  const logoDims = logoImage ? {w:logoImage.naturalWidth, h:logoImage.naturalHeight} : null;

  async function loadOrderPageImages(pageItems){
    const pageImages = {};
    await Promise.all(pageItems.map(async item=>{
      const src = PRODUCT_IMAGES[item.product.c];
      if(!src) return;
      const image = await loadPdfImage(src);
      if(image) pageImages[item.product.c] = image;
    }));
    return pageImages;
  }

  function drawHeader(){
    doc.setFillColor(255,248,247); doc.rect(0,0,pageW,pageH,'F');
    doc.setFillColor(255,255,255); doc.roundedRect(margin,10,pageW-margin*2,27,2.5,2.5,'F');
    doc.setDrawColor(241,194,188); doc.roundedRect(margin,10,pageW-margin*2,27,2.5,2.5,'S');
    if(logoDims){
      const lh = 12, lw = lh*(logoDims.w/logoDims.h);
      doc.addImage(logoImage, 'PNG', margin+4, 13, lw, lh);
    }
    doc.setFont('helvetica','bold'); doc.setFontSize(15); doc.setTextColor(184,24,16);
    doc.text('Solicitação — Seridóplast', margin+30, 18);
    doc.setFont('helvetica','italic'); doc.setFontSize(8.5); doc.setTextColor(120,50,45);
    doc.text('Acreditamos na força do trabalho', margin+30, 23.5);
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(120,120,120);
    doc.text(`RCA: ${rca.name} · ${items.length} produto(s) · fotos e preços opcionais`, margin+30, 29);
    doc.setDrawColor(226,35,26); doc.setFillColor(226,35,26);
    doc.rect(margin, 39, pageW-margin*2, 0.8, 'F');
  }

  function drawTableHeader(y){
    doc.setFillColor(251,233,231);
    doc.rect(margin, y, colWidths.reduce((a,b)=>a+b,0), rowH, 'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(8.5); doc.setTextColor(184,24,16);
    let x = margin;
    columns.forEach((c,i)=>{ doc.text(c, x+2, y+5.5); x += colWidths[i]; });
  }

  function drawOrderRow(item, y, index, image){
    if(index % 2 === 1){ doc.setFillColor(250,250,250); doc.rect(margin, y, colWidths.reduce((a,b)=>a+b,0), rowH, 'F'); }
    let x = margin;
    const imageBoxW = colWidths[0]-5, imageBoxH = rowH-4;
    if(image){
      const scale = Math.min(imageBoxW/image.w, imageBoxH/image.h);
      const imageW = image.w*scale, imageH = image.h*scale;
      const imageX = x + (colWidths[0]-imageW)/2, imageY = y + (rowH-imageH)/2;
      try{ doc.addImage(image.data, 'JPEG', imageX, imageY, imageW, imageH); }catch(e){}
    }else{
      doc.setFillColor(244,244,244); doc.roundedRect(x+3, y+3, colWidths[0]-6, rowH-6, 1, 1, 'F');
      doc.setFont('helvetica','normal'); doc.setFontSize(6.3); doc.setTextColor(160,160,160);
      doc.text('Sem foto', x+colWidths[0]/2, y+10, {align:'center'});
    }
    x += colWidths[0];

    doc.setFont('helvetica','bold'); doc.setFontSize(7.6); doc.setTextColor(184,24,16);
    doc.text(item.product.c, x+2, y+9.8);
    x += colWidths[1];

    doc.setFont('helvetica','bold'); doc.setFontSize(7.2); doc.setTextColor(30,30,30);
    const productLines = doc.splitTextToSize(item.product.d, colWidths[2]-4).slice(0,2);
    doc.text(productLines, x+2, y+5.2);
    doc.setFont('helvetica','normal'); doc.setFontSize(6.2); doc.setTextColor(115,115,115);
    doc.text(item.product.f, x+2, y+15);
    x += colWidths[2];

    doc.setFont('helvetica','bold'); doc.setFontSize(7.2); doc.setTextColor(30,30,30);
    doc.text(`${item.qty} ${item.product.u}`, x+2, y+9.8);
    x += colWidths[3];
    doc.setFont('helvetica','normal'); doc.setFontSize(7); doc.setTextColor(30,30,30);
    doc.text(item.price === null ? '—' : formatCurrency(item.price), x+2, y+9.8);
    x += colWidths[4];
    doc.setFont('helvetica','bold');
    doc.text(item.price === null ? '—' : formatCurrency(item.price * item.qty), x+2, y+9.8);

    doc.setDrawColor(238,238,238);
    doc.line(margin, y+rowH, margin+colWidths.reduce((a,b)=>a+b,0), y+rowH);
  }

  for(let pageIndex=0; pageIndex<totalPages; pageIndex++){
    if(pageIndex > 0) doc.addPage();
    drawHeader();
    let y = 43;
    drawTableHeader(y);
    y += 8;
    const pageItems = items.slice(pageIndex*rowsPerPage, (pageIndex+1)*rowsPerPage);
    const pageImages = await loadOrderPageImages(pageItems);
    pageItems.forEach((item, index)=>{
      drawOrderRow(item, y, index, pageImages[item.product.c]);
      y += rowH;
    });
    if(pageIndex === totalPages-1){
      y += 6;
      doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(27,30,34);
      doc.text(doc.splitTextToSize(summaryText, pageW-margin*2), pageW-margin, y, { align:'right' });
    }
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(140,140,140);
    doc.setFillColor(226,35,26); doc.rect(margin, pageH-11, 1.6, 1.6, 'F');
    doc.text(`Seridóplast · Solicitação preparada para ${rca.name}`, margin+3.5, pageH-9.7);
    doc.text(`Página ${pageIndex+1} de ${totalPages}`, pageW-margin, pageH-9.7, { align:'right' });
  }

  doc.save(filename);
}

pdfBtn.addEventListener('click', ()=>{
  if(!validateRequest()) return;
  const rca = selectedRca();
  const codes = Object.keys(cart);
  const items = codes.map(code=>({
    product:PRODUCTS_BY_CODE[code],
    qty:cart[code],
    price:Object.prototype.hasOwnProperty.call(cartPrices, code) ? cartPrices[code] : null
  }));
  const totalItens = codes.reduce((a,c)=>a+cart[c],0);
  const pricedCodes = codes.filter(code=>Object.prototype.hasOwnProperty.call(cartPrices, code));
  const totalPrice = pricedCodes.reduce((sum, code)=>sum + cart[code]*cartPrices[code], 0);
  const summaryText = `Total geral: ${codes.length} produto(s) · ${totalItens} ${totalItens===1?'volume':'volumes'} · ${pricedCodes.length ? `Valor informado: ${formatCurrency(totalPrice)}${pricedCodes.length < codes.length ? ` · ${codes.length-pricedCodes.length} sem preço` : ''}` : 'Preços não informados'}`;
  const origText = pdfBtn.textContent;
  pdfBtn.textContent = 'Gerando PDF…';
  pdfBtn.disabled = true;
  generateOrderPDF(
    'pedido-serido-plast.pdf',
    items,
    summaryText,
    rca
  ).finally(()=>{
    pdfBtn.textContent = origText;
    pdfBtn.disabled = false;
  });
});

